#include <vector>
#include <cstddef>
#include <omp.h>

void squareEach(std::vector<int> &x) {
    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());
    int *const data = x.data();

    #pragma omp parallel for default(none) shared(data, n) schedule(static)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        const long long v = static_cast<long long>(data[i]);
        data[i] = static_cast<int>(v * v);
    }
}
